    values_cte_name = f"{cte_name}_values"
    values_cols = {col: f"__review_value_{idx}" for idx, col in enumerate(specs)}
    values_select = ",\n                ".join(
        f"{_review_context_values_expr(
            source_alias=source_alias,
            source_col=source_col,
